import { ConditionalElement } from './conditional-element';
/**
 * The purpose of the DynamicLoop is to allow the framework to easily
 * re-create a list of elements within a container.
 *
 * A great example is a UL element that draws based on a list of
 * objects in the web-component.  Whenever the array changes,
 * they will want to call updateDynamicLoops. Through that, redrawChildren()
 * will get called which replaces the old children with whatever comes out of
 * the renderChildren function.
 */
export class DynamicLoop {
    constructor(renderChildren) {
        this.renderChildren = renderChildren;
    }
    redrawChildren() {
        this.parentElement.replaceChildren(...this.renderChildren().map((element) => {
            if (element instanceof ConditionalElement) {
                return element.renderElementOrPlaceholder();
            }
            else {
                return element;
            }
        }));
    }
    //To be called by the createElement function
    setParent(element) {
        this.parentElement = element;
    }
}
